contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address operator, address from, uint256 tokenId, bytes calldata data) public payable {
        bytes4 result;
        bool reverted;
        try c.onERC721Received(operator, from, tokenId, data) returns (bytes4 r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || result == bytes4(0x150b7a02));
    }
}

